const base = "https://ghproxy.net/https://raw.githubusercontent.com/mattpocock/skills/main/";
const paths = [
  "docs/productivity/grill-me.md",
  "skills/productivity/grill-me/SKILL.md",
  "plugins/productivity/grill-me/SKILL.md",
  ".claude-plugin/plugin.json",
];
const script = paths.map(p => `
try {
  $r = curl.exe -sS -m 20 -L "${base}${p}"
  $t = ($r -join "\`n")
  if ($t.Length -lt 60) { "### ${p} :: NOT FOUND / len=$($t.Length)" }
  else { "### ${p} :: len=$($t.Length)"; if ($t.Length -gt 3000) { $t.Substring($t.Length - 2600) } else { $t } }
} catch { "### ${p} :: ERR $($_.Exception.Message)" }
`).join("\n");
const out = await tools.pwsh({ command: script, description: "Fetch remaining grill-me files via proxy", timeoutMs: 120000 });
if (out.kind === "foreground") console.log(out.stdout.text.slice(0, 7000), "\nSTDERR:", out.stderr.text.slice(0, 300));
